const { SITE_ORIGIN, buildPublicIndex } = require('./_posts');

// Posts/pages with `external: true` (paths not generated by the CMS, e.g. the
// original hand-built article and the SEO landing page) provide their own
// <url> entry via the posts/pages collections below, so they must not also be
// listed here or the sitemap will contain a duplicate.
const STATIC_URLS = [
  { loc: '/', changefreq: 'weekly', priority: '1.0' },
  { loc: '/blog/', changefreq: 'weekly', priority: '0.8' },
  { loc: '/case-studies/', changefreq: 'monthly', priority: '0.8' },
  { loc: '/contact/', changefreq: 'yearly', priority: '0.7' },
  { loc: '/case-studies/gsa-contract-services/', changefreq: 'monthly', priority: '0.8' },
];

function escapeXml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

function buildSitemap(posts, pages) {
  const published = buildPublicIndex(posts);
  const publishedPages = (pages || []).filter((p) => p.status === 'published');
  const today = todayIso();
  const staticEntries = STATIC_URLS.map(
    (u) =>
      `  <url>\n    <loc>${SITE_ORIGIN}${u.loc}</loc>\n    <lastmod>${today}</lastmod>\n    <changefreq>${u.changefreq}</changefreq>\n    <priority>${u.priority}</priority>\n  </url>`
  );
  const postEntries = published.map(
    (p) =>
      `  <url>\n    <loc>${SITE_ORIGIN}${p.url}</loc>\n    <lastmod>${(p.publishDate || today).slice(0, 10)}</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.6</priority>\n  </url>`
  );
  const pageEntries = publishedPages.map(
    (p) =>
      `  <url>\n    <loc>${SITE_ORIGIN}/${p.slug}/</loc>\n    <lastmod>${(p.updatedAt || today).slice(0, 10)}</lastmod>\n    <changefreq>${p.external ? 'weekly' : 'monthly'}</changefreq>\n    <priority>${p.external ? '0.9' : '0.7'}</priority>\n  </url>`
  );
  return (
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
    staticEntries.concat(pageEntries).concat(postEntries).join('\n') +
    '\n</urlset>\n'
  );
}

function buildRss(posts) {
  const published = buildPublicIndex(posts);
  const items = published
    .map(
      (p) =>
        `    <item>\n` +
        `      <title>${escapeXml(p.title)}</title>\n` +
        `      <link>${SITE_ORIGIN}${p.url}</link>\n` +
        `      <guid>${SITE_ORIGIN}${p.url}</guid>\n` +
        `      <pubDate>${new Date(p.publishDate || Date.now()).toUTCString()}</pubDate>\n` +
        `      <description>${escapeXml(p.excerpt || '')}</description>\n` +
        `    </item>`
    )
    .join('\n');
  return (
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<rss version="2.0">\n' +
    '<channel>\n' +
    '  <title>Prabal Raj Shakya — Blog</title>\n' +
    `  <link>${SITE_ORIGIN}/blog/</link>\n` +
    '  <description>SEO and digital marketing insights for Nepali businesses.</description>\n' +
    '  <language>en</language>\n' +
    `  <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>\n` +
    items +
    '\n</channel>\n' +
    '</rss>\n'
  );
}

// llms.txt: a plain-text map of the site for AI tools. Lists only what is
// published right now, so scheduled or draft posts never appear early.
function buildLlmsTxt(posts, pages) {
  const published = buildPublicIndex(posts);
  const clean = (t) => String(t || '').replace(/\s+/g, ' ').trim();
  const pageLines = (pages || [])
    .filter((p) => p.status === 'published')
    .map((p) => `- [${clean(p.title)}](${SITE_ORIGIN}/${p.slug}/): ${clean(p.metaDescription) || 'SEO work and how I approach it.'}`);
  const postLines = published.map((p) => `- [${clean(p.title)}](${SITE_ORIGIN}${p.url}): ${clean(p.excerpt)}`);
  return (
    '# Prabal Raj Shakya\n\n' +
    '> Digital Marketing Specialist based in Kathmandu, Nepal. I do SEO, technical audits, answer engine optimization (AEO), paid social, email automation and short-form video. I lead SEO and website strategy at GSA Contract Services.\n\n' +
    'This site is a personal portfolio and blog. Guides are written by Prabal Raj Shakya and show their last-updated date and sources.\n\n' +
    '## Main pages\n\n' +
    `- [Home](${SITE_ORIGIN}/): Experience, skills, tools, certifications and contact details.\n` +
    pageLines.join('\n') + (pageLines.length ? '\n' : '') +
    `- [Contact](${SITE_ORIGIN}/contact/): Send a message about an SEO or digital marketing project. Replies within a day.\n` +
    `- [Case studies](${SITE_ORIGIN}/case-studies/): SEO case studies with the audit, the fixes and the results.\n` +
    `- [Case study: How SEO helped GSA Contract Services grow organic search clicks 8x](${SITE_ORIGIN}/case-studies/gsa-contract-services/): Audit, service pages and direct-answer content, with Search Console and GA4 results.\n` +
    `- [Blog](${SITE_ORIGIN}/blog/): All published articles.\n\n` +
    '## Blog posts\n\n' +
    (postLines.length ? postLines.join('\n') : '- No posts published yet.') + '\n\n' +
    '## Contact\n\n' +
    '- Email: prabalraj980@gmail.com\n' +
    '- [LinkedIn](https://linkedin.com/in/prabal-raj-shakya-b640222b7)\n' +
    '- [Behance](https://behance.net/prabalshakya)\n\n' +
    '## Optional\n\n' +
    `- [Sitemap](${SITE_ORIGIN}/sitemap.xml)\n` +
    `- [RSS feed](${SITE_ORIGIN}/rss.xml)\n`
  );
}

module.exports = { buildSitemap, buildRss, buildLlmsTxt };
